\set ON_ERROR_STOP on
SELECT format('SELECT %L AS relation, count(*) AS rows, encode(sha256(convert_to(COALESCE(string_agg(row_to_json(t)::text, E''\n'' ORDER BY row_to_json(t)::text), ''''), ''UTF8'')), ''hex'') AS content_sha256 FROM %I.%I t;', n.nspname||'.'||c.relname, n.nspname,c.relname)
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE c.relkind='r' AND n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND c.relname NOT LIKE 'restore_fail%' ORDER BY n.nspname,c.relname
\gexec
SELECT 'schema',nspname,pg_get_userbyid(nspowner),COALESCE(nspacl::text,'DEFAULT') FROM pg_namespace WHERE nspname NOT IN ('pg_catalog','information_schema') AND nspname NOT LIKE 'pg_%' ORDER BY nspname;
SELECT 'relation',n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),COALESCE(c.relacl::text,'DEFAULT') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%' AND c.relname NOT LIKE 'restore_fail%' ORDER BY n.nspname,c.relname;
SELECT 'function',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_userbyid(p.proowner),COALESCE(p.proacl::text,'DEFAULT') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%' AND p.proname NOT LIKE 'restore_fail%' ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid);
SELECT 'effective_schema',n.nspname,r.rolname,has_schema_privilege(r.oid,n.oid,'USAGE'),has_schema_privilege(r.oid,n.oid,'CREATE') FROM pg_namespace n CROSS JOIN pg_roles r WHERE n.nspname IN ('auth','dq','gold','meta','ml','obs','ops','ref') AND r.rolname IN ('ketrika_app','copilot_ro') ORDER BY n.nspname,r.rolname;
SELECT 'effective_table',n.nspname,c.relname,r.rolname,has_table_privilege(r.oid,c.oid,'SELECT'),has_table_privilege(r.oid,c.oid,'INSERT'),has_table_privilege(r.oid,c.oid,'UPDATE'),has_table_privilege(r.oid,c.oid,'DELETE') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN pg_roles r WHERE n.nspname IN ('auth','dq','gold','meta','ml','obs','ops','ref') AND c.relkind IN ('r','v','m') AND r.rolname IN ('ketrika_app','copilot_ro') ORDER BY n.nspname,c.relname,r.rolname;
SELECT 'default_acl',pg_get_userbyid(d.defaclrole),COALESCE(n.nspname,''),d.defaclobjtype,d.defaclacl::text FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace ORDER BY 2,3,4;
SELECT 'column_acl',n.nspname,c.relname,a.attname,a.attacl::text FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE a.attacl IS NOT NULL AND n.nspname NOT LIKE 'pg_%' AND c.relname NOT LIKE 'restore_fail%' ORDER BY 2,3,4;
SELECT 'row_security',n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN ('auth','dq','gold','meta','ml','obs','ops','ref') ORDER BY 2,3;
